import React, { useState } from "react";
import "./BudgetLimits.css";
import Navbar from "./Navbar";

function BudgetLimits({ selectedCategories = [], onNext, onBack, limits: initialLimits = {} }) {

  const [limits, setLimits] = useState(initialLimits);

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSave = () => {
    if (Object.keys(limits).length === 0) {
      alert("Please enter at least one budget");
      return;
    }

    onNext(limits);
  };

  return (
    <>
      <Navbar 
  title="Budget Limits" 
  onBack={onBack} 
  onNext={handleSave}
/>

      <div style={{ paddingTop: "80px" }}>
        <div className="budget-page" style={{ paddingBottom: "60px" }}>
          <div className="budget-wrapper">

            <div className="budget-header">
              <h1>Set Monthly Budget Limits</h1>
              <p>Define spending per category</p>
            </div>

            <div className="budget-grid">
              {selectedCategories.map(cat => (
                <div className="budget-card" key={cat}>
                  <h3>{cat}</h3>

                  <input
                    type="number"
                    className="budget-input"
                    value={limits[cat] || ""}
                    onChange={(e) => handleChange(cat, e.target.value)}
                  />
                </div>
              ))}
            </div>

            <div style={{ marginTop: "40px", textAlign: "center" }}>
              <button onClick={handleSave}>
                Save Limits
              </button>
            </div>

          </div>
        </div>
      </div>
    </>
  );
}

export default BudgetLimits;
